// 科目题库：英语（由 exam-bank.js 拆分而来，内容未改动）
window.SUBJECT_BANK = window.SUBJECT_BANK || {};
window.SUBJECT_BANK['english'] = {"id":"english","name":"英语","chapters":[{"id":"english-c1","name":"词汇"},{"id":"english-c2","name":"情景"},{"id":"english-c3","name":"语法"},{"id":"english-c4","name":"阅读"}],"questions":[{"id":"english-vocab-1","origNo":1,"type":"single","stem":"The new policy will ______ the living standards of the people in rural areas.","options":[{"key":"A","text":"affect"},{"key":"B","text":"effect"},{"key":"C","text":"afford"},{"key":"D","text":"effort"}],"answer":"A","explanation":"句意：这项新政策将影响农村地区人民的生活水平。affect 意为\"影响\"（动词），符合语境；effect 作动词时意为\"促成\"，作名词才是\"影响\"；afford 意为\"负担得起\"；effort 意为\"努力\"（名词）。故选A。","chapter":"词汇"},{"id":"english-vocab-2","origNo":2,"type":"single","stem":"She has made up her mind to ______ the task even if it means working overtime.","options":[{"key":"A","text":"accomplish"},{"key":"B","text":"accompany"},{"key":"C","text":"accumulate"},{"key":"D","text":"accommodate"}],"answer":"A","explanation":"句意：即使要加班，她也已下定决心完成这项任务。make up one's mind to do sth 意为\"下定决心做某事\"；accomplish 意为\"完成（任务）\"，符合语境；accompany 陪伴；accumulate 积累；accommodate 容纳、提供住宿。故选A。","chapter":"词汇"},{"id":"english-vocab-3","origNo":3,"type":"single","stem":"The manager was ______ of stealing company funds and was later dismissed.","options":[{"key":"A","text":"accused"},{"key":"B","text":"charged"},{"key":"C","text":"blamed"},{"key":"D","text":"scolded"}],"answer":"A","explanation":"句意：这位经理被指控盗取公司资金，随后被解雇。be accused of 意为\"被指控……\"，固定搭配；charge 搭配 with（be charged with）；blame 责备；scold 斥责。故选A。","chapter":"词汇"},{"id":"english-vocab-4","origNo":4,"type":"single","stem":"The old building was completely ______ by fire last night, leaving nothing but ashes.","options":[{"key":"A","text":"damaged"},{"key":"B","text":"ruined"},{"key":"C","text":"destroyed"},{"key":"D","text":"hurt"}],"answer":"C","explanation":"句意：昨晚那栋旧建筑被大火彻底摧毁，只留下灰烬。destroy 意为\"彻底摧毁\"，程度最重，与\"leaving nothing but ashes（只留灰烬）\"吻合；damage 损害（程度较轻）；ruin 毁坏；hurt 多指伤害人或身体。故选C。","chapter":"词汇"},{"id":"english-vocab-5","origNo":5,"type":"single","stem":"You should ______ the opportunity to learn from experienced colleagues while you are still a new employee.","options":[{"key":"A","text":"take"},{"key":"B","text":"make"},{"key":"C","text":"get"},{"key":"D","text":"seize"}],"answer":"D","explanation":"句意：趁你还是新员工，你应该抓住向有经验的同事学习的机会。seize the opportunity 意为\"抓住机会\"，固定搭配，seize 更强调\"把握、抓住\"；take/make/get 也可搭配 opportunity，但 seize 最契合\"珍惜机会\"的语境。故选D。","chapter":"词汇"},{"id":"english-vocab-6","origNo":6,"type":"single","stem":"The conference has been ______ until next Friday due to the unexpected absence of the keynote speaker.","options":[{"key":"A","text":"put off"},{"key":"B","text":"put away"},{"key":"C","text":"put out"},{"key":"D","text":"put up"}],"answer":"A","explanation":"句意：由于主讲人意外缺席，会议已推迟到下周五。put off 意为\"推迟\"；put away 收好、放好；put out 扑灭；put up 张贴、搭建。故选A。","chapter":"词汇"},{"id":"english-vocab-7","origNo":7,"type":"single","stem":"He is a very ______ person and never gets angry even when others are rude to him.","options":[{"key":"A","text":"patient"},{"key":"B","text":"confident"},{"key":"C","text":"tolerant"},{"key":"D","text":"modest"}],"answer":"C","explanation":"句意：他是一个非常宽容的人，即使别人对他粗鲁也从不生气。tolerant 意为\"宽容的、能容忍的\"，符合\"别人粗鲁也不生气\"；patient 侧重\"耐心的\"；confident 自信的；modest 谦虚的。故选C。","chapter":"词汇"},{"id":"english-vocab-8","origNo":8,"type":"single","stem":"The company is ______ new ways to reduce production costs without sacrificing product quality.","options":[{"key":"A","text":"looking after"},{"key":"B","text":"looking into"},{"key":"C","text":"looking for"},{"key":"D","text":"looking up"}],"answer":"C","explanation":"句意：公司正在寻找在不牺牲产品质量的前提下降低生产成本的新方法。look for 意为\"寻找\"；look after 照顾；look into 调查；look up 查阅、抬头看。故选C。","chapter":"词汇"},{"id":"english-vocab-9","origNo":9,"type":"single","stem":"It is ______ that all students should arrive at the examination hall at least 15 minutes before the test starts.","options":[{"key":"A","text":"requested"},{"key":"B","text":"demanded"},{"key":"C","text":"required"},{"key":"D","text":"acquired"}],"answer":"C","explanation":"句意：所有学生应在考试开始前至少15分钟到达考场，这是规定要求。It is required that... 意为\"要求/规定……\"，表硬性规定；request 请求（语气较弱）；demand 多用于主动要求；acquire 获得。故选C。","chapter":"词汇"},{"id":"english-vocab-10","origNo":10,"type":"single","stem":"She ______ her success to hard work and perseverance rather than to luck.","options":[{"key":"A","text":"contributes"},{"key":"B","text":"distributes"},{"key":"C","text":"attributes"},{"key":"D","text":"dedicates"}],"answer":"C","explanation":"句意：她把自己的成功归因于努力和毅力，而不是运气。attribute...to... 意为\"把……归因于……\"；contribute to 贡献；distribute 分发；dedicate...to... 奉献。故选C。","chapter":"词汇"},{"id":"english-vocab-11","origNo":11,"type":"single","stem":"I can’t ______ the difference between these two words, as they seem to have exactly the same meaning.","options":[{"key":"A","text":"tell"},{"key":"B","text":"say"},{"key":"C","text":"speak"},{"key":"D","text":"talk"}],"answer":"A","explanation":"句意：我分辨不出这两个词的区别，因为它们似乎意思完全相同。tell the difference 意为\"辨别差异\"，固定搭配；say 说；speak 讲（语言）；talk 谈话。故选A。","chapter":"词汇"},{"id":"english-vocab-12","origNo":12,"type":"single","stem":"The newly published book ______ a wide range of topics, from history to modern technology.","options":[{"key":"A","text":"covers"},{"key":"B","text":"contains"},{"key":"C","text":"includes"},{"key":"D","text":"concludes"}],"answer":"A","explanation":"句意：这本新出版的书涵盖了从历史到现代科技的广泛话题。cover 意为\"涵盖、覆盖（范围）\"，常用于书籍、课程涵盖主题；contain 包含（强调内含）；include 包括；conclude 总结。故选A。","chapter":"词汇"},{"id":"english-vocab-13","origNo":13,"type":"single","stem":"The doctor ______ him to give up smoking for the sake of his health, but he just wouldn’t listen.","options":[{"key":"A","text":"persuaded"},{"key":"B","text":"advised"},{"key":"C","text":"suggested"},{"key":"D","text":"convinced"}],"answer":"B","explanation":"句意：医生为他的健康劝他戒烟，但他就是不听。advise sb to do sth 意为\"建议某人做某事\"，固定搭配；persuade sb to do sth 强调\"已说服成功\"（但他没听，说明未成功）；suggest 后不接 sb to do；convince 说服（思想上的信服）。故选B。","chapter":"词汇"},{"id":"english-vocab-14","origNo":14,"type":"single","stem":"The witness’s account of the accident didn’t ______ with what the other witnesses had reported.","options":[{"key":"A","text":"agree"},{"key":"B","text":"correspond"},{"key":"C","text":"match"},{"key":"D","text":"compare"}],"answer":"B","explanation":"句意：这位证人对事故的陈述与其他证人报告的情况不一致。correspond with 意为\"与……相符、一致\"，常用于陈述、证词等书面内容；agree with 也可表一致，但更常用于意见、食物；match 多指\"匹配\"（及物）；compare 比较。故选B。","chapter":"词汇"},{"id":"english-vocab-15","origNo":15,"type":"single","stem":"The little boy showed great ______ in solving the difficult math problem all by himself.","options":[{"key":"A","text":"intelligence"},{"key":"B","text":"wisdom"},{"key":"C","text":"talent"},{"key":"D","text":"ability"}],"answer":"A","explanation":"句意：这个小男孩独自解出了那道数学难题，表现出很高的智力。intelligence 意为\"智力、聪明\"，show great intelligence 表现出很高智力；wisdom 智慧；talent 天赋；ability 能力。故选A。","chapter":"词汇"},{"id":"english-vocab-16","origNo":16,"type":"single","stem":"The two countries have finally reached an ______ to cooperate in the field of environmental protection.","options":[{"key":"A","text":"agreement"},{"key":"B","text":"arrangement"},{"key":"C","text":"appointment"},{"key":"D","text":"approval"}],"answer":"A","explanation":"句意：两国终于达成了一项在环保领域合作的协议。reach an agreement 意为\"达成协议\"，固定搭配；arrangement 安排；appointment 预约、任命；approval 批准。故选A。","chapter":"词汇"},{"id":"english-vocab-17","origNo":17,"type":"single","stem":"He is ______ to lose his temper when things don’t go his way, so you’d better be careful.","options":[{"key":"A","text":"likely"},{"key":"B","text":"probable"},{"key":"C","text":"possible"},{"key":"D","text":"liable"}],"answer":"D","explanation":"句意：事情不顺他意时他很容易发脾气，所以你最好小心。be liable to do sth 意为\"易于……的、有……倾向的\"，多指人脾气、性格上的倾向；likely 也可表\"可能\"，但 liable 更贴合\"易于动怒\"的性格；probable/possible 不以人作主语。故选D。","chapter":"词汇"},{"id":"english-vocab-18","origNo":18,"type":"single","stem":"The old professor has ______ a large number of outstanding students who have made great contributions to society.","options":[{"key":"A","text":"trained"},{"key":"B","text":"educated"},{"key":"C","text":"cultivated"},{"key":"D","text":"brought"}],"answer":"C","explanation":"句意：这位老教授培养了一大批对社会做出巨大贡献的优秀学生。cultivate 意为\"培养（人才）\"，符合教授培养学生；train 训练；educate 教育；bring 带来（bring up 才是\"培养\"）。故选C。","chapter":"词汇"},{"id":"english-vocab-19","origNo":19,"type":"single","stem":"The film was so ______ that many people in the audience were moved to tears.","options":[{"key":"A","text":"touched"},{"key":"B","text":"touching"},{"key":"C","text":"moved"},{"key":"D","text":"moving"}],"answer":"B","explanation":"句意：这部电影如此感人，以至于观众中许多人都被感动得落泪。touching 意为\"令人感动的\"，修饰物（film）；touched/moved 意为\"被感动的\"，修饰人；moving 也可修饰物，但 touching 更侧重温情动人，与\"moved to tears（感动落泪）\"呼应。故选B。","chapter":"词汇"},{"id":"english-vocab-20","origNo":20,"type":"single","stem":"It is reported that the government will ______ a new set of measures to deal with air pollution.","options":[{"key":"A","text":"adopt"},{"key":"B","text":"adapt"},{"key":"C","text":"adjust"},{"key":"D","text":"admit"}],"answer":"A","explanation":"句意：据报道，政府将采取一套新措施来应对空气污染。adopt 意为\"采纳、采取（措施/政策）\"；adapt 适应、改编；adjust 调整；admit 承认。此为形近词辨析。故选A。","chapter":"词汇"},{"id":"english-scene-1","origNo":1,"type":"single","stem":"— Hey, my favorite band’s playing at the campus festival next Friday! — Wait, _________ — confirm our group work division now?","options":[{"key":"A","text":"Please turn over a new leaf"},{"key":"B","text":"Don’t pull our weight"},{"key":"C","text":"Let’s stick to the point"},{"key":"D","text":"You ticked all the right box"}],"answer":"C","explanation":"句意：——嘿，我最喜欢的乐队下周五要在校园节上演出！——等等，我们还是说正事吧，现在确认一下小组作业的分工？对方在谈乐队演出（偏离正题），说话人想拉回小组作业的话题，Let's stick to the point 意为\"我们紧扣主题、说正事吧\"。故选C。","chapter":"情景"},{"id":"english-scene-2","origNo":2,"type":"single","stem":"— Good news! I’ve found a summer job! — _________. Anything interesting?","options":[{"key":"A","text":"It’s a good idea"},{"key":"B","text":"You can’t be serious"},{"key":"C","text":"That’s great"},{"key":"D","text":"Check it out for yourself"}],"answer":"C","explanation":"句意：——好消息！我找到一份暑假工作了！——太棒了。有什么有趣的吗？对方告知找到暑假工作（好消息），应表示祝贺，That's great 意为\"太棒了\"。故选C。","chapter":"情景"},{"id":"english-scene-3","origNo":3,"type":"single","stem":"— How did you find the film *Zootopia 2*? — _________. I can’t think too highly of it.","options":[{"key":"A","text":"It makes no sense"},{"key":"B","text":"It’s up to you"},{"key":"C","text":"It’s awful"},{"key":"D","text":"It’s really amazing"}],"answer":"D","explanation":"句意：——你觉得电影《疯狂动物城2》怎么样？——非常精彩。我再怎么称赞都不为过。How did you find... 意为\"你觉得……怎么样\"；I can't think too highly of it 意为\"我对它评价极高（再怎么称赞都不为过）\"，是高度肯定，故选 It's really amazing（非常精彩）。故选D。","chapter":"情景"},{"id":"english-scene-4","origNo":4,"type":"single","stem":"— Here is a new edition of *China Daily*. Do you want to have a look? — _________! Let me see it.","options":[{"key":"A","text":"Don’t bother"},{"key":"B","text":"Not really"},{"key":"C","text":"By all means"},{"key":"D","text":"Mind your own business"}],"answer":"C","explanation":"句意：——这是一份新版《中国日报》。你想看看吗？——当然可以！让我看看。由后文\"Let me see it（让我看看）\"可知欣然接受，By all means 意为\"当然可以、没问题\"。故选C。","chapter":"情景"},{"id":"english-scene-5","origNo":5,"type":"single","stem":"—Skipping breakfast is a good way to lose weight. —______. Actually it has the opposite effect.","options":[{"key":"A","text":"I’m glad to know that"},{"key":"B","text":"I can’t agree more"},{"key":"C","text":"That’s not the case"},{"key":"D","text":"That’s for sure"}],"answer":"C","explanation":"句意：——不吃早餐是减肥的好办法。——并非如此。实际上它效果正好相反。由\"Actually it has the opposite effect（实际上效果相反）\"可知要反驳对方，That's not the case 意为\"并非如此\"。故选C。","chapter":"情景"},{"id":"english-scene-6","origNo":6,"type":"single","stem":"—You seem to be in a really good mood. —I finished my final examination today. ________! Now I’m free.","options":[{"key":"A","text":"What a coincidence"},{"key":"B","text":"What a relief"},{"key":"C","text":"I have got it"},{"key":"D","text":"I have had enough."}],"answer":"B","explanation":"句意：——你看起来心情很好。——我今天考完期末考试了。真让人松了口气！现在我自由了。考完期末考试、重获自由，心情轻松，What a relief 意为\"真松了一口气\"。故选B。","chapter":"情景"},{"id":"english-scene-7","origNo":7,"type":"single","stem":"— I feel very thankful for your help when a serious accident happened to my brother yesterday. — ______. But luckily, he had a narrow escape.","options":[{"key":"A","text":"Don’t worry about it"},{"key":"B","text":"Don’t overemphasize it"},{"key":"C","text":"Don’t take it seriously"},{"key":"D","text":"Don’t mention it"}],"answer":"D","explanation":"句意：——昨天我哥哥出了严重事故，非常感谢你的帮助。——别客气。不过幸运的是，他死里逃生。对方表达感谢，应礼貌回应，Don't mention it 意为\"别客气、不用谢\"。故选D。","chapter":"情景"},{"id":"english-scene-8","origNo":8,"type":"single","stem":"— I plan to sign up for the school’s debate competition, but I’m worried about my public speaking skills. — ________. You’ve been practicing debates in class for months and you’re ready for it.","options":[{"key":"A","text":"I’d rather you didn’t"},{"key":"B","text":"That’s a bad idea"},{"key":"C","text":"You’ve got this"},{"key":"D","text":"Never mind"}],"answer":"C","explanation":"句意：——我打算报名参加学校的辩论赛，但我担心自己的演讲能力。——你能行的。你在课堂上练了好几个月辩论，已经准备好了。对方犹豫担心，应给予鼓励，You've got this 意为\"你能行、没问题\"。故选C。","chapter":"情景"},{"id":"english-scene-9","origNo":9,"type":"single","stem":"— Excuse me, could you tell me what you think about my proposal of organizing the campus book fair? I’ve prepared several plans but I’m not sure if they are practical… — ________. Just tell me the core idea of your plan and whether you have got the school’s approval or not.","options":[{"key":"A","text":"Don’t beat around the bush"},{"key":"B","text":"I’m all ears"},{"key":"C","text":"You can say that again"},{"key":"D","text":"It’s a piece of cake"}],"answer":"A","explanation":"句意：——打扰一下，你能说说对我组织校园书展这个提议的看法吗？我准备了好几个方案，但不确定是否可行……——别绕弯子了。直接告诉我你计划的核心想法，以及你是否已获得学校批准。对方绕来绕去讲不清，说话人希望直入主题，Don't beat around the bush 意为\"别绕弯子、直说吧\"，由后文\"Just tell me the core idea...（直接告诉我核心想法）\"可印证。故选A。","chapter":"情景"},{"id":"english-scene-10","origNo":10,"type":"single","stem":"—I think this contemporary abstract painting just looks like a mess of colours. —______. Actually, I find it quite meaningful.","options":[{"key":"A","text":"I beg to differ"},{"key":"B","text":"You read my mind"},{"key":"C","text":"I couldn’t agree more"},{"key":"D","text":"You’ve got me there"}],"answer":"A","explanation":"句意：——我觉得这幅当代抽象画就像一团乱糟糟的颜色。——恕我不能苟同。实际上，我觉得它挺有意义的。由\"Actually, I find it quite meaningful（实际上我觉得它挺有意义）\"可知自己不同意，I beg to differ 意为\"恕我不能苟同\"，用于礼貌表达不同意见。故选A。","chapter":"情景"},{"id":"english-scene-11","origNo":11,"type":"single","stem":"—It’s a real dilemma. I can't decide which major to choose. Physics and literature both appeal to me. —______. But you should choose the one that you are most passionate about.","options":[{"key":"A","text":"It’s a deal"},{"key":"B","text":"Never say never"},{"key":"C","text":"Don't mention it"},{"key":"D","text":"That's a tough call"}],"answer":"D","explanation":"句意：——这真是个两难的选择。我决定不了选哪个专业。物理和文学都很吸引我。——确实难抉择。但你应该选你最热爱的那个。对方面临两难选择，说话人表示理解，That's a tough call 意为\"确实很难抉择\"。故选D。","chapter":"情景"},{"id":"english-scene-12","origNo":12,"type":"single","stem":"The research team will _________ during the expedition (探险), as they must continue collecting data despite the approaching storm.","options":[{"key":"A","text":"rain cats and dogs"},{"key":"B","text":"brave the elements"},{"key":"C","text":"burn the midnight oil"},{"key":"D","text":"beat around the bush"}],"answer":"B","explanation":"句意：探险期间，研究队将顶风冒雨，因为尽管暴风雨逼近，他们仍必须继续收集数据。brave the elements 意为\"顶风冒雨、冒着恶劣天气\"，符合\"暴风雨逼近仍继续工作\"；rain cats and dogs 倾盆大雨；burn the midnight oil 熬夜；beat around the bush 绕弯子。故选B。","chapter":"情景"},{"id":"english-scene-13","origNo":13,"type":"single","stem":"—I stayed up all night cramming for the math test, and now I can’t remember a single formula! —Ugh, ________ when you try to memorize everything at the last minute. Next time, maybe study a little each day instead?","options":[{"key":"A","text":"that happens"},{"key":"B","text":"it turns"},{"key":"C","text":"this exists"},{"key":"D","text":"there arises"}],"answer":"A","explanation":"句意：——我熬了一整夜突击数学考试，现在却一个公式都记不起来！——唉，临到最后一刻才想死记硬背，这种事常有。下次也许每天学一点？对方熬夜突击却记不住，说话人予以安慰，that happens 意为\"这种事常有、难免的\"。故选A。","chapter":"情景"},{"id":"english-scene-14","origNo":14,"type":"single","stem":"— Say, what’s your favorite sport? — Hmmm... it’s hard to say. I like golf a lot — but I guess I like tennis better. — Do you play much tennis? — Yes, quite a bit. ______ — Sorry. I’m strictly a spectator — football, baseball, basketball, golf... I watch them all.","options":[{"key":"A","text":"Where do you often spend your weekend?"},{"key":"B","text":"Who is your favorite player?"},{"key":"C","text":"Why don’t you do exercise regularly?"},{"key":"D","text":"How about a game sometime?"}],"answer":"D","explanation":"句意：——说说，你最喜欢的运动是什么？——嗯……很难说。我很喜欢高尔夫——不过我想我更喜欢网球。——你常打网球吗？——是的，常打。改天来比一场怎么样？——抱歉。我纯粹是个观众——足球、棒球、篮球、高尔夫……我都只看。谈论完喜爱的运动（网球）后自然提出邀约，How about a game sometime? 意为\"改天来比一场怎么样？\"。故选D。","chapter":"情景"},{"id":"english-scene-15","origNo":15,"type":"single","stem":"— Excuse me, is this seat taken? — No. it isn’t. — ______, so my friend and I can sit together? — No, not at all. — Thanks a lot.","options":[{"key":"A","text":"Would you leave me alone for a while"},{"key":"B","text":"Would you mind getting out of my sight"},{"key":"C","text":"Would you mind moving over one"},{"key":"D","text":"Would my friend take your seat"}],"answer":"C","explanation":"句意：——打扰一下，这个座位有人吗？——没有。——你介意往旁边挪一个位子吗，这样我和朋友就能坐一起？——一点也不介意。——多谢。由\"so my friend and I can sit together（这样我和朋友能坐一起）\"可知请求对方挪位，Would you mind moving over one 意为\"你介意往旁边挪一个位子吗\"。故选C。","chapter":"情景"},{"id":"english-scene-16","origNo":16,"type":"single","stem":"— What time is it? — It’s a quarter to five. — ______ — Five or five-thirty. He said it didn’t make any difference.","options":[{"key":"A","text":"Jim is waiting for us — let’s hurry up!"},{"key":"B","text":"Where are we expected to meet Jim later?"},{"key":"C","text":"Jim is said to be with us at five tomorrow afternoon."},{"key":"D","text":"Aren’t we supposed to be at Jim’s house by five o’ clock?"}],"answer":"D","explanation":"句意：——几点了？——差一刻五点。——我们不是该五点到吉姆家吗？——五点或五点半都行。他说没关系。问完时间后，由答语\"Five or five-thirty（五点或五点半）\"可知在讨论约定时间，Aren't we supposed to be at Jim's house by five o'clock? 意为\"我们不是该五点到吉姆家吗？\"。故选D。","chapter":"情景"},{"id":"english-scene-17","origNo":17,"type":"single","stem":"— Haven’t I seen you somewhere before? — No, I don’t think so. — But you do look familiar. Wait a second... I know... We were on the same flight to New York last month. — Oh, yes. Now I remember. What a coincidence to meet in San Francisco! — Well, you know what they say — ______.","options":[{"key":"A","text":"it’s a small world."},{"key":"B","text":"you are so forgetful."},{"key":"C","text":"it’s the flight where stories begin."},{"key":"D","text":"you cannot step into the same river twice."}],"answer":"A","explanation":"句意：——我们是不是在哪儿见过？——没有，我觉得没有。——但你看着确实眼熟。等一下……我知道了……我们上个月坐的是同一班去纽约的航班。——哦，对。现在我想起来了。在旧金山碰到真是太巧了！——嗯，俗话说——世界真小。异地偶遇故人，感慨巧合，it's a small world 意为\"世界真小\"，是常用俗语。故选A。","chapter":"情景"},{"id":"english-scene-18","origNo":18,"type":"single","stem":"— Excuse me. I wonder if you can help me. — Sure. What is it? — I want to have my hair cut, but I can’t find a barber shop. — I know where one is.______","options":[{"key":"A","text":"I’m not so sure."},{"key":"B","text":"Come on — I’ll show you."},{"key":"C","text":"It sells cool T-shirts."},{"key":"D","text":"You won’t take the wrong way."}],"answer":"B","explanation":"句意：——打扰一下，不知你能否帮个忙。——当然。什么事？——我想理发，但找不到理发店。——我知道有一家在哪。来，我带你去。对方请求帮忙找理发店，说话人主动带路，Come on — I'll show you. 意为\"来，我带你去/指给你看\"。故选B。","chapter":"情景"},{"id":"english-scene-19","origNo":19,"type":"single","stem":"— Diana and I went for a drive in the country on Saturday. — ______. Where did you go?","options":[{"key":"A","text":"That sounds nice"},{"key":"B","text":"Not really"},{"key":"C","text":"Thank goodness"},{"key":"D","text":"Take it seriously"}],"answer":"A","explanation":"句意：——星期六我和戴安娜去乡下兜风了。——听起来不错。你们去哪儿了？对方分享周六郊游兜风，应表示赞同，That sounds nice 意为\"听起来不错\"，由后文\"Where did you go?（去哪儿了？）\"可知感兴趣。故选A。","chapter":"情景"},{"id":"english-scene-20","origNo":20,"type":"single","stem":"-The team worked together and solved the technical problem in just two hours. -See? _____","options":[{"key":"A","text":"Every cloud has a silver lining."},{"key":"B","text":"Too many cooks spoil the broth."},{"key":"C","text":"Many hands make light work."},{"key":"D","text":"The early bird catches the worm."}],"answer":"C","explanation":"句意：——团队齐心协力，仅用两小时就解决了技术难题。——看见了吧？人多好办事。团队协作快速解决问题，Many hands make light work 意为\"人多好办事/众人拾柴火焰高\"，强调合作使工作轻松。故选C。","chapter":"情景"},{"id":"english-gram-1","origNo":1,"type":"single","stem":"—Is your brother going camping? —He’s signed up but he’s considering________.","options":[{"key":"A","text":"not to go"},{"key":"B","text":"not going"},{"key":"C","text":"won’t go"},{"key":"D","text":"not go"}],"answer":"B","explanation":"句意：——你哥哥要去露营吗？——他报名了，但他在考虑不去了。consider 后接动名词 doing，否定形式为 not doing，故用 not going。故选B。","chapter":"语法"},{"id":"english-gram-2","origNo":2,"type":"single","stem":"In nature some animals actively defend the area_________ they depend for the resources.","options":[{"key":"A","text":"in which"},{"key":"B","text":"on which"},{"key":"C","text":"which"},{"key":"D","text":"where"}],"answer":"B","explanation":"句意：在自然界中，一些动物会积极保卫它们赖以获取资源的领地。定语从句修饰 area，动词短语为 depend on the area（依赖该领地），介词 on 提前，用\"介词+which\"结构即 on which。故选B。","chapter":"语法"},{"id":"english-gram-3","origNo":3,"type":"single","stem":"—What a terrible accident! —Yes. It happened __________ he four roads meet.","options":[{"key":"A","text":"where"},{"key":"B","text":"that"},{"key":"C","text":"when"},{"key":"D","text":"as"}],"answer":"A","explanation":"句意：——多可怕的事故！——是的。事故发生在四条路交汇的地方。where 引导地点状语从句，意为\"在……的地方\"，说明事故发生的地点。故选A。","chapter":"语法"},{"id":"english-gram-4","origNo":4,"type":"single","stem":"Mr. White, who I ______ to the south of France, still lives in London.","options":[{"key":"A","text":"think to have moved"},{"key":"B","text":"think had moved"},{"key":"C","text":"thought have moved"},{"key":"D","text":"thought had moved"}],"answer":"D","explanation":"句意：怀特先生，我原以为他已经搬到法国南部了，现在仍住在伦敦。主句谓语 thought 为过去时，move（搬家）发生在 thought 之前，即\"过去的过去\"，用过去完成时 had moved。故选D。","chapter":"语法"},{"id":"english-gram-5","origNo":5,"type":"single","stem":"The officers narrowly escaped ___________ in the hot battle.","options":[{"key":"A","text":"have killed"},{"key":"B","text":"to kill"},{"key":"C","text":"to be killed"},{"key":"D","text":"being killed"}],"answer":"D","explanation":"句意：军官们在激烈的战斗中险些丧命。escape 后接动名词 doing；officers 与 kill 为被动关系（被杀），用动名词的被动式 being killed。故选D。","chapter":"语法"},{"id":"english-gram-6","origNo":6,"type":"single","stem":"The plan has to be ______ to meet the real situation.","options":[{"key":"A","text":"adjusted"},{"key":"B","text":"adapted"},{"key":"C","text":"produced"},{"key":"D","text":"refunded"}],"answer":"A","explanation":"句意：计划必须加以调整以符合实际情况。be adjusted to 意为\"被调整以适应……\"，adjust 侧重\"调整（细节、计划）以符合\"；adapt 侧重\"适应（环境）\"；produced 生产；refunded 退款。故选A。","chapter":"语法"},{"id":"english-gram-7","origNo":7,"type":"single","stem":"_______about her ideal university, Jenny said she had no idea.","options":[{"key":"A","text":"Ask"},{"key":"B","text":"When asking"},{"key":"C","text":"Asking"},{"key":"D","text":"When asked"}],"answer":"D","explanation":"句意：当被问及理想大学时，珍妮说她还没想好。Jenny 与 ask 之间是被动关系（被问），用过去分词表被动，When asked 意为\"当被问到时\"。故选D。","chapter":"语法"},{"id":"english-gram-8","origNo":8,"type":"single","stem":"I showed him the pictures I _______ of the animals the day before.","options":[{"key":"A","text":"was taken"},{"key":"B","text":"have taken"},{"key":"C","text":"had taken"},{"key":"D","text":"was taking"}],"answer":"C","explanation":"句意：我给他看了我前一天拍的动物照片。\"拍照\"发生在\"showed（给他看）\"之前，即\"过去的过去\"，用过去完成时 had taken。故选C。","chapter":"语法"},{"id":"english-gram-9","origNo":9,"type":"single","stem":"Look at the sign, Sir. We don’t permit ________ in the hall.","options":[{"key":"A","text":"smoke"},{"key":"B","text":"to smoke"},{"key":"C","text":"smoking"},{"key":"D","text":"to have a smoke"}],"answer":"C","explanation":"句意：先生，请看标识。我们不允许在大厅里吸烟。permit 后接动名词 permit doing sth，意为\"允许做某事\"，故用 smoking。故选C。","chapter":"语法"},{"id":"english-gram-10","origNo":10,"type":"single","stem":"Even the best writers sometimes find themselves________ for words.","options":[{"key":"A","text":"losing"},{"key":"B","text":"lost"},{"key":"C","text":"loses"},{"key":"D","text":"be lost"}],"answer":"B","explanation":"句意：即使是最优秀的作家有时也会发现自己一时语塞。find oneself + 过去分词表状态；be lost for words 意为\"一时语塞、说不出话\"，用过去分词 lost 作宾补。故选B。","chapter":"语法"},{"id":"english-gram-11","origNo":11,"type":"single","stem":"Most environmental problems exist because adequate measures for preventing them _______ taken in the past.","options":[{"key":"A","text":"had not been"},{"key":"B","text":"were not being"},{"key":"C","text":"were not"},{"key":"D","text":"was not"}],"answer":"C","explanation":"句意：大多数环境问题之所以存在，是因为过去没有采取足够的预防措施。measures 与 take 为被动关系，时间状语 in the past 表一般过去时，用一般过去时的被动语态 were not taken。故选C。","chapter":"语法"},{"id":"english-gram-12","origNo":12,"type":"single","stem":"He ran as fast as he could _____ to catch the early bus.","options":[{"key":"A","text":"to hope"},{"key":"B","text":"hope"},{"key":"C","text":"hoping"},{"key":"D","text":"hoped"}],"answer":"C","explanation":"句意：他尽可能快地跑，希望能赶上早班公交。hoping 作伴随状语，用现在分词表伴随动作，he 与 hope 为主动关系。故选C。","chapter":"语法"},{"id":"english-gram-13","origNo":13,"type":"single","stem":"You should be careful how you judge people ________ you cannot sum up a man's life in one moment.","options":[{"key":"A","text":"as though"},{"key":"B","text":"even though"},{"key":"C","text":"now that"},{"key":"D","text":"in that"}],"answer":"D","explanation":"句意：你判断人时应谨慎，因为你不可能在一瞬间概括一个人的一生。in that 意为\"因为、在于\"，引导原因状语从句，符合\"应谨慎判断\"的原因；as though 仿佛；even though 即使；now that 既然。故选D。","chapter":"语法"},{"id":"english-gram-14","origNo":14,"type":"single","stem":"—I haven't heard from John for a long time. —What do you suppose ________ to him?","options":[{"key":"A","text":"was happening"},{"key":"B","text":"to happen"},{"key":"C","text":"has happened"},{"key":"D","text":"had happened"}],"answer":"C","explanation":"句意：——我很久没收到约翰的消息了。——你认为他发生了什么事？询问到现在为止发生了什么，强调对现在的影响，用现在完成时 has happened。故选C。","chapter":"语法"},{"id":"english-gram-15","origNo":15,"type":"single","stem":"____ at home, we can enjoy music or watch live sports games.","options":[{"key":"A","text":"To sit"},{"key":"B","text":"Sitting"},{"key":"C","text":"Sitted"},{"key":"D","text":"Being sitted"}],"answer":"B","explanation":"句意：坐在家里，我们可以欣赏音乐或观看体育直播。Sitting at home 意为\"坐在家里\"，现在分词作状语，we 与 sit 为主动关系。故选B。","chapter":"语法"},{"id":"english-gram-16","origNo":16,"type":"single","stem":"You will find the laptop well-designed when he ______ it ______.","options":[{"key":"A","text":"will bring …back"},{"key":"B","text":"brings …back"},{"key":"C","text":"takes …away"},{"key":"D","text":"will take …away"}],"answer":"B","explanation":"句意：等他把笔记本电脑带回来，你就会发现它设计得很好。when 引导时间状语从句，遵循\"主将从现\"原则（主句将来时，从句用一般现在时），用 brings back；且语境是\"带回来\"才看得到设计。故选B。","chapter":"语法"},{"id":"english-gram-17","origNo":17,"type":"single","stem":"If you apply yourself to ______ about the problem, you will soon solve it.","options":[{"key":"A","text":"think"},{"key":"B","text":"be thought"},{"key":"C","text":"thinking"},{"key":"D","text":"have thought"}],"answer":"C","explanation":"句意：如果你专心思考这个问题，很快就能解决它。apply oneself to 中 to 为介词，后接动名词，故用 thinking。故选C。","chapter":"语法"},{"id":"english-gram-18","origNo":18,"type":"single","stem":"There_______a sports meeting last week.","options":[{"key":"A","text":"be"},{"key":"B","text":"is"},{"key":"C","text":"was"},{"key":"D","text":"had"}],"answer":"C","explanation":"句意：上周举行了一场运动会。There be 句型表\"存在/发生\"，时间状语 last week 表一般过去时，主语 a sports meeting 为单数，用 There was。故选C。","chapter":"语法"},{"id":"english-gram-19","origNo":19,"type":"single","stem":"The ceremony of Syria’s admission into the Belt and Road Initiative (BRI)________ in the capital Damascus on Jan. 12 and was attended by Fadi Khalil, head of the commission, who noted that Syria________ one of the main countries on the ancient Silk Road, particularly the cities of Aleppo and Palmyra.","options":[{"key":"A","text":"took place; had been"},{"key":"B","text":"was taken place; has been"},{"key":"C","text":"was taken place; was"},{"key":"D","text":"took place; was"}],"answer":"D","explanation":"句意：1月12日，叙利亚加入\"一带一路\"倡议的仪式在首都大马士革举行，委员会主席法迪·哈利勒出席了仪式；他指出，叙利亚曾是古丝绸之路上的主要国家之一，尤其是阿勒颇和巴尔米拉两座城市。take place（举行）无被动语态，用 took place；was attended 表\"被出席\"已给出；后文描述叙利亚过去\"曾是\"古丝绸之路主要国家，用一般过去时 was。故选D。","chapter":"语法"},{"id":"english-gram-20","origNo":20,"type":"single","stem":"What is it _____ his daughter needs most?","options":[{"key":"A","text":"what"},{"key":"B","text":"which"},{"key":"C","text":"that"},{"key":"D","text":"if"}],"answer":"C","explanation":"句意：他女儿最需要的是什么？这是强调句型的疑问形式 What is it that...，强调句结构为\"It is/was + 被强调部分 + that...\"，疑问句用 What is it that...，故用 that。故选C。","chapter":"语法"},{"id":"english-read-1","origNo":1,"type":"single","stem":"【阅读材料】\n“Kevin! Kevin! Did you hear what I said?” Ms. Reed, the band director,\nlooked straight at him — she wanted him to take Robin’s place, since\nRobin had broken her arm, and play a solo at the concert. Kevin agreed,\ntrying hard to hide his sadness: he was terrified of performing on\nstage, *freezing up* completely when playing alone, even though he was\nthe best saxophone player in his middle school band and played with the\nsenior high band too.\nJames, his bandmate, felt sorry for him and shared how he’d fainted on\nstage during a solo because he was so nervous. The story only made Kevin\nmore worried, but something worse was coming. Kelly, the overly\ncompetitive top flutist in the state, stopped him, saying that the Youth\nSymphony director would come to the concert to listen to his solo — and\nif he played well, he could get a chance to try out. Her words made him\nfeel heavy inside; he’d wanted to join the Youth Symphony for a long\ntime but never had the courage to audition.\nRunning out of the school, Kevin thought of excuses to skip the solo:\npretending to be ill, saying he’d hurt his finger. But he knew his\nparents would see he was lying, and hurting his finger on purpose was\ntoo dangerous. By the time he got home, his mom was very happy, talking\nexcitedly about the Youth Symphony chance and Ms. Reed’s praise. Kevin\nlied that his day was okay, then went down to the furnace room — called\n“Kevin’s Dungeon” — his practice space. He picked up his saxophone, took\na deep breath, and started to play.\nThis time, he didn’t focus on the fear of messing up; he focused on the\nmusic he loved. Maybe this solo wasn’t a nightmare — it was a chance to\nturn his dream into reality.\nThe final note faded, and loud applause burst out. Kevin smiled and felt\na warm rush of joy in his heart. He finally understood that courage\nisn’t the lack of fear, but going ahead in spite of it. Dreams never\ncome to those who run away from challenges; they always wait for those\nwho dare to face their fears and try.\n\n【题目】\nWhy did Ms. Reed ask Kevin to play the solo at the concert?","options":[{"key":"A","text":"Kevin was the most skilled sax player in the senior high band."},{"key":"B","text":"Robin was unable to perform due to a broken arm."},{"key":"C","text":"The Youth Symphony director personally recommended Kevin."},{"key":"D","text":"Kevin had been eager to get the solo opportunity for a long time."}],"answer":"B","explanation":"句意（题目）：里德老师为什么让凯文在音乐会上独奏？\n【原文依据】第一段：\"she wanted him to take Robin's place, since Robin had broken her arm\"（她想让他代替罗宾，因为罗宾摔断了胳膊）。即罗宾因手臂受伤无法演出，里德老师才请凯文顶替。\n【逐项分析】A 错：原文说凯文是\"middle school band（中学乐队）\"里最好的萨克斯手，并非\"senior high band（高中乐队）\"里最好；C 错：青年交响乐团总监是来\"听\"他独奏的，并非\"亲自推荐\"他；D 错：凯文一直想加入青年交响乐团但\"没勇气去试\"，并非\"一直渴望独奏机会\"。故选B。","chapter":"阅读"},{"id":"english-read-2","origNo":2,"type":"single","stem":"【阅读材料】\n“Kevin! Kevin! Did you hear what I said?” Ms. Reed, the band director,\nlooked straight at him — she wanted him to take Robin’s place, since\nRobin had broken her arm, and play a solo at the concert. Kevin agreed,\ntrying hard to hide his sadness: he was terrified of performing on\nstage, *freezing up* completely when playing alone, even though he was\nthe best saxophone player in his middle school band and played with the\nsenior high band too.\nJames, his bandmate, felt sorry for him and shared how he’d fainted on\nstage during a solo because he was so nervous. The story only made Kevin\nmore worried, but something worse was coming. Kelly, the overly\ncompetitive top flutist in the state, stopped him, saying that the Youth\nSymphony director would come to the concert to listen to his solo — and\nif he played well, he could get a chance to try out. Her words made him\nfeel heavy inside; he’d wanted to join the Youth Symphony for a long\ntime but never had the courage to audition.\nRunning out of the school, Kevin thought of excuses to skip the solo:\npretending to be ill, saying he’d hurt his finger. But he knew his\nparents would see he was lying, and hurting his finger on purpose was\ntoo dangerous. By the time he got home, his mom was very happy, talking\nexcitedly about the Youth Symphony chance and Ms. Reed’s praise. Kevin\nlied that his day was okay, then went down to the furnace room — called\n“Kevin’s Dungeon” — his practice space. He picked up his saxophone, took\na deep breath, and started to play.\nThis time, he didn’t focus on the fear of messing up; he focused on the\nmusic he loved. Maybe this solo wasn’t a nightmare — it was a chance to\nturn his dream into reality.\nThe final note faded, and loud applause burst out. Kevin smiled and felt\na warm rush of joy in his heart. He finally understood that courage\nisn’t the lack of fear, but going ahead in spite of it. Dreams never\ncome to those who run away from challenges; they always wait for those\nwho dare to face their fears and try.\n\n【题目】\nThe underlined phrase “freezing up” in Paragraph 1 probably means _________.","options":[{"key":"A","text":"staying calm to deal with the performance"},{"key":"B","text":"feeling extremely cold on the frightening stage"},{"key":"C","text":"having great confidence in playing the solo"},{"key":"D","text":"being unable to move or act because of nervousness"}],"answer":"D","explanation":"句意（题目）：第一段中划线短语\"freezing up\"最可能的意思是？\n【原文依据】第一段：\"he was terrified of performing on stage, freezing up completely when playing alone\"（他害怕上台表演，独奏时会完全 freezing up）。\"terrified（极度恐惧）\"说明是紧张导致的反应。\n【逐项分析】A 错：\"保持冷静\"与\"terrified（恐惧）\"矛盾；B 错：这是借喻，并非真觉得舞台寒冷；C 错：\"充满信心\"与原文\"害怕上台\"相反；D 对：因紧张而僵住、无法动弹，符合恐惧表演的语境。故选D。","chapter":"阅读"},{"id":"english-read-3","origNo":3,"type":"single","stem":"【阅读材料】\n“Kevin! Kevin! Did you hear what I said?” Ms. Reed, the band director,\nlooked straight at him — she wanted him to take Robin’s place, since\nRobin had broken her arm, and play a solo at the concert. Kevin agreed,\ntrying hard to hide his sadness: he was terrified of performing on\nstage, *freezing up* completely when playing alone, even though he was\nthe best saxophone player in his middle school band and played with the\nsenior high band too.\nJames, his bandmate, felt sorry for him and shared how he’d fainted on\nstage during a solo because he was so nervous. The story only made Kevin\nmore worried, but something worse was coming. Kelly, the overly\ncompetitive top flutist in the state, stopped him, saying that the Youth\nSymphony director would come to the concert to listen to his solo — and\nif he played well, he could get a chance to try out. Her words made him\nfeel heavy inside; he’d wanted to join the Youth Symphony for a long\ntime but never had the courage to audition.\nRunning out of the school, Kevin thought of excuses to skip the solo:\npretending to be ill, saying he’d hurt his finger. But he knew his\nparents would see he was lying, and hurting his finger on purpose was\ntoo dangerous. By the time he got home, his mom was very happy, talking\nexcitedly about the Youth Symphony chance and Ms. Reed’s praise. Kevin\nlied that his day was okay, then went down to the furnace room — called\n“Kevin’s Dungeon” — his practice space. He picked up his saxophone, took\na deep breath, and started to play.\nThis time, he didn’t focus on the fear of messing up; he focused on the\nmusic he loved. Maybe this solo wasn’t a nightmare — it was a chance to\nturn his dream into reality.\nThe final note faded, and loud applause burst out. Kevin smiled and felt\na warm rush of joy in his heart. He finally understood that courage\nisn’t the lack of fear, but going ahead in spite of it. Dreams never\ncome to those who run away from challenges; they always wait for those\nwho dare to face their fears and try.\n\n【题目】\nWhat made Kevin’s anxiety grow after he received the solo task?","options":[{"key":"A","text":"James told him about his own embarrassing solo experience."},{"key":"B","text":"His mother didn’t believe he could perform well on stage."},{"key":"C","text":"Kelly laughed at him for lacking the courage to audition."},{"key":"D","text":"He found his practice room was too small to play the saxophone."}],"answer":"A","explanation":"句意（题目）：凯文接到独奏任务后，是什么让他的焦虑加剧了？\n【原文依据】第二段：\"James... shared how he'd fainted on stage during a solo because he was so nervous. The story only made Kevin more worried\"（詹姆斯讲述了自己因太紧张在独奏时晕倒在台上，这个故事让凯文更担心了）。\n【逐项分析】B 错：原文未提母亲不相信他，反而母亲\"非常高兴\"；C 错：凯利是告诉他总监要来听，并非\"嘲笑他没勇气试音\"；D 错：练习室\"凯文的地窖\"是他自己的练习空间，原文没说它太小。故选A。","chapter":"阅读"},{"id":"english-read-4","origNo":4,"type":"single","stem":"【阅读材料】\n“Kevin! Kevin! Did you hear what I said?” Ms. Reed, the band director,\nlooked straight at him — she wanted him to take Robin’s place, since\nRobin had broken her arm, and play a solo at the concert. Kevin agreed,\ntrying hard to hide his sadness: he was terrified of performing on\nstage, *freezing up* completely when playing alone, even though he was\nthe best saxophone player in his middle school band and played with the\nsenior high band too.\nJames, his bandmate, felt sorry for him and shared how he’d fainted on\nstage during a solo because he was so nervous. The story only made Kevin\nmore worried, but something worse was coming. Kelly, the overly\ncompetitive top flutist in the state, stopped him, saying that the Youth\nSymphony director would come to the concert to listen to his solo — and\nif he played well, he could get a chance to try out. Her words made him\nfeel heavy inside; he’d wanted to join the Youth Symphony for a long\ntime but never had the courage to audition.\nRunning out of the school, Kevin thought of excuses to skip the solo:\npretending to be ill, saying he’d hurt his finger. But he knew his\nparents would see he was lying, and hurting his finger on purpose was\ntoo dangerous. By the time he got home, his mom was very happy, talking\nexcitedly about the Youth Symphony chance and Ms. Reed’s praise. Kevin\nlied that his day was okay, then went down to the furnace room — called\n“Kevin’s Dungeon” — his practice space. He picked up his saxophone, took\na deep breath, and started to play.\nThis time, he didn’t focus on the fear of messing up; he focused on the\nmusic he loved. Maybe this solo wasn’t a nightmare — it was a chance to\nturn his dream into reality.\nThe final note faded, and loud applause burst out. Kevin smiled and felt\na warm rush of joy in his heart. He finally understood that courage\nisn’t the lack of fear, but going ahead in spite of it. Dreams never\ncome to those who run away from challenges; they always wait for those\nwho dare to face their fears and try.\n\n【题目】\nWe can infer from the last paragraph that Kevin finally chose to _________.","options":[{"key":"A","text":"pretend to be sick and miss the concert instantly"},{"key":"B","text":"gave up his dream of joining the Youth Symphony"},{"key":"C","text":"face the challenge and practice for the solo actively"},{"key":"D","text":"ask the band director to replace him with another student"}],"answer":"C","explanation":"句意（题目）：从最后一段可推断凯文最终选择了什么？\n【原文依据】第三、四段：\"He picked up his saxophone, took a deep breath, and started to play... he focused on the music he loved... it was a chance to turn his dream into reality\"（他拿起萨克斯、深呼吸、开始吹奏，专注于自己热爱的音乐，把独奏视为实现梦想的机会）。\n【逐项分析】A 错：他曾想装病逃避，但最终没有这么做；B 错：他没有放弃加入青年交响乐团的梦想，反而把它当机会；D 错：原文没提他请老师换人，他是自己面对的。故选C。","chapter":"阅读"},{"id":"english-read-5","origNo":5,"type":"single","stem":"【阅读材料】\n“Kevin! Kevin! Did you hear what I said?” Ms. Reed, the band director,\nlooked straight at him — she wanted him to take Robin’s place, since\nRobin had broken her arm, and play a solo at the concert. Kevin agreed,\ntrying hard to hide his sadness: he was terrified of performing on\nstage, *freezing up* completely when playing alone, even though he was\nthe best saxophone player in his middle school band and played with the\nsenior high band too.\nJames, his bandmate, felt sorry for him and shared how he’d fainted on\nstage during a solo because he was so nervous. The story only made Kevin\nmore worried, but something worse was coming. Kelly, the overly\ncompetitive top flutist in the state, stopped him, saying that the Youth\nSymphony director would come to the concert to listen to his solo — and\nif he played well, he could get a chance to try out. Her words made him\nfeel heavy inside; he’d wanted to join the Youth Symphony for a long\ntime but never had the courage to audition.\nRunning out of the school, Kevin thought of excuses to skip the solo:\npretending to be ill, saying he’d hurt his finger. But he knew his\nparents would see he was lying, and hurting his finger on purpose was\ntoo dangerous. By the time he got home, his mom was very happy, talking\nexcitedly about the Youth Symphony chance and Ms. Reed’s praise. Kevin\nlied that his day was okay, then went down to the furnace room — called\n“Kevin’s Dungeon” — his practice space. He picked up his saxophone, took\na deep breath, and started to play.\nThis time, he didn’t focus on the fear of messing up; he focused on the\nmusic he loved. Maybe this solo wasn’t a nightmare — it was a chance to\nturn his dream into reality.\nThe final note faded, and loud applause burst out. Kevin smiled and felt\na warm rush of joy in his heart. He finally understood that courage\nisn’t the lack of fear, but going ahead in spite of it. Dreams never\ncome to those who run away from challenges; they always wait for those\nwho dare to face their fears and try.\n\n【题目】\nWhat is the best title for the passage?","options":[{"key":"A","text":"A Successful Solo Performance"},{"key":"B","text":"The Competitive Flutist Kelly"},{"key":"C","text":"A Strict, Generous and Kind Band Director"},{"key":"D","text":"Stage Fright and A New Chance"}],"answer":"D","explanation":"句意（题目）：本文最合适的标题是？\n【原文依据】全文围绕凯文\"害怕上台（stage fright）\"展开，最终他抓住独奏这个\"新机会（a new chance）\"克服恐惧、实现梦想，末段点题：\"courage isn't the lack of fear, but going ahead in spite of it\"（勇气不是没有恐惧，而是带着恐惧前行）。\n【逐项分析】A\"一场成功的独奏演出\"只覆盖结尾，未涵盖\"克服恐惧\"这一主线；B\"好胜的长笛手凯利\"只是配角；C\"严格慷慨善良的乐队指挥\"文中里德老师着墨不多，非主角；D\"舞台恐惧与新机会\"既点出冲突又点出转折，最能概括全文。故选D。","chapter":"阅读"},{"id":"english-read-6","origNo":6,"type":"single","stem":"【阅读材料】\nThe 2026 CCTV Spring Festival Gala featured a breathtaking performance\nthat seamlessly blended traditional Chinese martial arts with\ncutting-edge technology: a carefully designed martial arts routine\nperformed by humanoid robots. This was not merely entertainment for the\naudience; it was a powerful declaration of China’s rapid and impressive\nadvancements in the fields of robotics and artificial intelligence.\nCompared to their debut just a year earlier, the 2026 robots\ndemonstrated astonishing progress in every aspect. Gone were the stiff,\nawkward and hesitant movements of the past. Dozens of Unitree’s G1\nhumanoid robots perfectly carried out complex and skillful actions,\nincluding high-speed flips, synchronized (同步的) nunchaku swings, and\neven the delicate, unsteady steps of “Drunken Fist.” They maintained\nstable balance, performed flawless formations, and interacted safely\nwith young human martial artists, a breakthrough that reflected huge\nleaps in both stability and dynamic motion control.\nBehind the striking performance lies a *convergence* of advanced\ntechnologies that together make such precise movements possible. Powered\nby highly developed AI control systems and equipped with LiDAR\n(激光雷达) sensors, the robots can map the 3D stage environment in real\ntime, enabling them to recognize their positions accurately and adjust\ntheir movements instantly to stay perfectly synchronized. Their flexible\njumps and flips rely on powerful actuators (执行器) and massive\nprofessional training data, proving that machines can now attain a level\nof athleticism once considered unique to humans.\nThe meaning of the display goes far beyond artistic effect. As a\nmilestone in intelligent manufacturing, the show underlines China’s\ngrowing competitiveness in the global humanoid robot industry. While\nChinese companies take a major share of the world market, the gala\nperformance more importantly shows the nation’s strong ability to\ncombine AI technology with a complete supply chain. It suggests a future\nwhere robots, having mastered the precision of kung fu, will undertake\ncomplex tasks in industry and daily life, turning technological strength\ninto practical social value.\n\n【题目】\nWhat was the most significant improvement in the 2026 robot performance compared to the previous year?","options":[{"key":"A","text":"The robots performed hesitant movements on a larger stage."},{"key":"B","text":"The robots moved more smoothly and performed complex actions."},{"key":"C","text":"The robots were controlled by young human performers."},{"key":"D","text":"The robots could speak and interact with the martial audience."}],"answer":"B","explanation":"句意（题目）：与上一年相比，2026年机器人表演最重大的改进是什么？\n【原文依据】第二段：\"Gone were the stiff, awkward and hesitant movements of the past... perfectly carried out complex and skillful actions\"（过去僵硬、笨拙、迟疑的动作不见了……完美完成了复杂精巧的动作）。\n【逐项分析】A 错：原文说僵硬迟疑的动作\"已经消失\"，而非\"在更大舞台上表演迟疑动作\"；C 错：机器人是与人类武术者\"安全互动\"，并非被人类表演者\"控制\"；D 错：原文未提机器人能\"说话\"。故选B。","chapter":"阅读"},{"id":"english-read-7","origNo":7,"type":"single","stem":"【阅读材料】\nThe 2026 CCTV Spring Festival Gala featured a breathtaking performance\nthat seamlessly blended traditional Chinese martial arts with\ncutting-edge technology: a carefully designed martial arts routine\nperformed by humanoid robots. This was not merely entertainment for the\naudience; it was a powerful declaration of China’s rapid and impressive\nadvancements in the fields of robotics and artificial intelligence.\nCompared to their debut just a year earlier, the 2026 robots\ndemonstrated astonishing progress in every aspect. Gone were the stiff,\nawkward and hesitant movements of the past. Dozens of Unitree’s G1\nhumanoid robots perfectly carried out complex and skillful actions,\nincluding high-speed flips, synchronized (同步的) nunchaku swings, and\neven the delicate, unsteady steps of “Drunken Fist.” They maintained\nstable balance, performed flawless formations, and interacted safely\nwith young human martial artists, a breakthrough that reflected huge\nleaps in both stability and dynamic motion control.\nBehind the striking performance lies a *convergence* of advanced\ntechnologies that together make such precise movements possible. Powered\nby highly developed AI control systems and equipped with LiDAR\n(激光雷达) sensors, the robots can map the 3D stage environment in real\ntime, enabling them to recognize their positions accurately and adjust\ntheir movements instantly to stay perfectly synchronized. Their flexible\njumps and flips rely on powerful actuators (执行器) and massive\nprofessional training data, proving that machines can now attain a level\nof athleticism once considered unique to humans.\nThe meaning of the display goes far beyond artistic effect. As a\nmilestone in intelligent manufacturing, the show underlines China’s\ngrowing competitiveness in the global humanoid robot industry. While\nChinese companies take a major share of the world market, the gala\nperformance more importantly shows the nation’s strong ability to\ncombine AI technology with a complete supply chain. It suggests a future\nwhere robots, having mastered the precision of kung fu, will undertake\ncomplex tasks in industry and daily life, turning technological strength\ninto practical social value.\n\n【题目】\nThe underlined word “convergence” in Paragraph 3 most probably means _________.","options":[{"key":"A","text":"combination"},{"key":"B","text":"competition"},{"key":"C","text":"conflict"},{"key":"D","text":"creativity"}],"answer":"A","explanation":"句意（题目）：第三段中划线词\"convergence\"最可能的意思是？\n【原文依据】第三段：\"a convergence of advanced technologies that together make such precise movements possible\"（先进技术的 convergence 共同使如此精准的动作成为可能）。关键线索是\"together（共同）\"——多种技术合在一起发挥作用。\n【逐项分析】B\"竞争\"、C\"冲突\"都与\"together（共同协作）\"相反；D\"创造力\"强调新颖，而此处强调的是多种技术\"结合\"。故选A（combination，融合/结合）。","chapter":"阅读"},{"id":"english-read-8","origNo":8,"type":"single","stem":"【阅读材料】\nThe 2026 CCTV Spring Festival Gala featured a breathtaking performance\nthat seamlessly blended traditional Chinese martial arts with\ncutting-edge technology: a carefully designed martial arts routine\nperformed by humanoid robots. This was not merely entertainment for the\naudience; it was a powerful declaration of China’s rapid and impressive\nadvancements in the fields of robotics and artificial intelligence.\nCompared to their debut just a year earlier, the 2026 robots\ndemonstrated astonishing progress in every aspect. Gone were the stiff,\nawkward and hesitant movements of the past. Dozens of Unitree’s G1\nhumanoid robots perfectly carried out complex and skillful actions,\nincluding high-speed flips, synchronized (同步的) nunchaku swings, and\neven the delicate, unsteady steps of “Drunken Fist.” They maintained\nstable balance, performed flawless formations, and interacted safely\nwith young human martial artists, a breakthrough that reflected huge\nleaps in both stability and dynamic motion control.\nBehind the striking performance lies a *convergence* of advanced\ntechnologies that together make such precise movements possible. Powered\nby highly developed AI control systems and equipped with LiDAR\n(激光雷达) sensors, the robots can map the 3D stage environment in real\ntime, enabling them to recognize their positions accurately and adjust\ntheir movements instantly to stay perfectly synchronized. Their flexible\njumps and flips rely on powerful actuators (执行器) and massive\nprofessional training data, proving that machines can now attain a level\nof athleticism once considered unique to humans.\nThe meaning of the display goes far beyond artistic effect. As a\nmilestone in intelligent manufacturing, the show underlines China’s\ngrowing competitiveness in the global humanoid robot industry. While\nChinese companies take a major share of the world market, the gala\nperformance more importantly shows the nation’s strong ability to\ncombine AI technology with a complete supply chain. It suggests a future\nwhere robots, having mastered the precision of kung fu, will undertake\ncomplex tasks in industry and daily life, turning technological strength\ninto practical social value.\n\n【题目】\nHow did the robots maintain perfect synchronization during the performance?","options":[{"key":"A","text":"They followed fixed routes without any adjustment."},{"key":"B","text":"They were remotely controlled by engineers behind the stage."},{"key":"C","text":"They used sensors to map the stage and adjust movements in real time."},{"key":"D","text":"They responded to voice commands from human performers."}],"answer":"C","explanation":"句意（题目）：机器人在表演中如何保持完美同步？\n【原文依据】第三段：\"equipped with LiDAR sensors, the robots can map the 3D stage environment in real time... adjust their movements instantly to stay perfectly synchronized\"（机器人配备激光雷达传感器，能实时绘制3D舞台环境……即时调整动作以保持完美同步）。\n【逐项分析】A 错：原文说它们\"即时调整\"，并非\"走固定路线不调整\"；B 错：是靠AI和传感器自主完成，并非\"后台工程师远程操控\"；D 错：原文未提\"语音指令\"。故选C。","chapter":"阅读"},{"id":"english-read-9","origNo":9,"type":"single","stem":"【阅读材料】\nThe 2026 CCTV Spring Festival Gala featured a breathtaking performance\nthat seamlessly blended traditional Chinese martial arts with\ncutting-edge technology: a carefully designed martial arts routine\nperformed by humanoid robots. This was not merely entertainment for the\naudience; it was a powerful declaration of China’s rapid and impressive\nadvancements in the fields of robotics and artificial intelligence.\nCompared to their debut just a year earlier, the 2026 robots\ndemonstrated astonishing progress in every aspect. Gone were the stiff,\nawkward and hesitant movements of the past. Dozens of Unitree’s G1\nhumanoid robots perfectly carried out complex and skillful actions,\nincluding high-speed flips, synchronized (同步的) nunchaku swings, and\neven the delicate, unsteady steps of “Drunken Fist.” They maintained\nstable balance, performed flawless formations, and interacted safely\nwith young human martial artists, a breakthrough that reflected huge\nleaps in both stability and dynamic motion control.\nBehind the striking performance lies a *convergence* of advanced\ntechnologies that together make such precise movements possible. Powered\nby highly developed AI control systems and equipped with LiDAR\n(激光雷达) sensors, the robots can map the 3D stage environment in real\ntime, enabling them to recognize their positions accurately and adjust\ntheir movements instantly to stay perfectly synchronized. Their flexible\njumps and flips rely on powerful actuators (执行器) and massive\nprofessional training data, proving that machines can now attain a level\nof athleticism once considered unique to humans.\nThe meaning of the display goes far beyond artistic effect. As a\nmilestone in intelligent manufacturing, the show underlines China’s\ngrowing competitiveness in the global humanoid robot industry. While\nChinese companies take a major share of the world market, the gala\nperformance more importantly shows the nation’s strong ability to\ncombine AI technology with a complete supply chain. It suggests a future\nwhere robots, having mastered the precision of kung fu, will undertake\ncomplex tasks in industry and daily life, turning technological strength\ninto practical social value.\n\n【题目】\nWhat can be inferred from the last paragraph?","options":[{"key":"A","text":"The performance was meant to show robots are better than humans at martial arts."},{"key":"B","text":"China has led the world in all fields of intelligent manufacturing."},{"key":"C","text":"Human performers will gradually disappear from traditional cultural galas."},{"key":"D","text":"The performance stood for China’s progress in AI and manufacturing integration."}],"answer":"D","explanation":"句意（题目）：从最后一段可以推断出什么？\n【原文依据】末段：\"the show underlines China's growing competitiveness in the global humanoid robot industry... ability to combine AI technology with a complete supply chain\"（这场表演凸显了中国在全球人形机器人产业日益增强的竞争力……将AI技术与完整供应链结合的能力）。\n【逐项分析】A 错：表演是展示技术与制造业融合，并非\"机器人比人类更擅长武术\"；B 错：\"在所有智能制造领域领先世界\"过于绝对，原文只说\"竞争力增强\"；C 错：原文未说人类表演者会\"逐渐消失\"。故选D。","chapter":"阅读"},{"id":"english-read-10","origNo":10,"type":"single","stem":"【阅读材料】\nThe 2026 CCTV Spring Festival Gala featured a breathtaking performance\nthat seamlessly blended traditional Chinese martial arts with\ncutting-edge technology: a carefully designed martial arts routine\nperformed by humanoid robots. This was not merely entertainment for the\naudience; it was a powerful declaration of China’s rapid and impressive\nadvancements in the fields of robotics and artificial intelligence.\nCompared to their debut just a year earlier, the 2026 robots\ndemonstrated astonishing progress in every aspect. Gone were the stiff,\nawkward and hesitant movements of the past. Dozens of Unitree’s G1\nhumanoid robots perfectly carried out complex and skillful actions,\nincluding high-speed flips, synchronized (同步的) nunchaku swings, and\neven the delicate, unsteady steps of “Drunken Fist.” They maintained\nstable balance, performed flawless formations, and interacted safely\nwith young human martial artists, a breakthrough that reflected huge\nleaps in both stability and dynamic motion control.\nBehind the striking performance lies a *convergence* of advanced\ntechnologies that together make such precise movements possible. Powered\nby highly developed AI control systems and equipped with LiDAR\n(激光雷达) sensors, the robots can map the 3D stage environment in real\ntime, enabling them to recognize their positions accurately and adjust\ntheir movements instantly to stay perfectly synchronized. Their flexible\njumps and flips rely on powerful actuators (执行器) and massive\nprofessional training data, proving that machines can now attain a level\nof athleticism once considered unique to humans.\nThe meaning of the display goes far beyond artistic effect. As a\nmilestone in intelligent manufacturing, the show underlines China’s\ngrowing competitiveness in the global humanoid robot industry. While\nChinese companies take a major share of the world market, the gala\nperformance more importantly shows the nation’s strong ability to\ncombine AI technology with a complete supply chain. It suggests a future\nwhere robots, having mastered the precision of kung fu, will undertake\ncomplex tasks in industry and daily life, turning technological strength\ninto practical social value.\n\n【题目】\nAccording to the passage, what future role are these robots expected to play?","options":[{"key":"A","text":"Replacing all human workers in factories."},{"key":"B","text":"Performing only in entertainment shows."},{"key":"C","text":"Taking on complex tasks in industry and daily life."},{"key":"D","text":"Competing in international martial arts competitions."}],"answer":"C","explanation":"句意（题目）：据文章，这些机器人未来预计将扮演什么角色？\n【原文依据】末段：\"robots... will undertake complex tasks in industry and daily life, turning technological strength into practical social value\"（机器人将在工业和日常生活中承担复杂任务，把技术实力转化为实用社会价值）。\n【逐项分析】A 错：\"取代所有人类工人\"过于绝对，原文只说\"承担复杂任务\"；B 错：原文明确说意义\"远超艺术效果\"，并非只在娱乐演出；D 错：原文未提\"参加国际武术比赛\"。故选C。","chapter":"阅读"},{"id":"english-read-11","origNo":11,"type":"single","stem":"【阅读材料】\nPersonal growth is often mistakenly regarded as a smooth upward path of\nachievements. Yet psychological research and real-life experiences\nconfirm a different truth: resilience — the ability to adapt and develop\namid difficulties  — is the unseen force driving deep and lasting\ngrowth. In an era of rapid changes and unexpected challenges, developing\nresilience is not just a survival skill but a key part of self-\ndevelopment, turning setbacks into stepping stones.\nThe link between difficulties and growth lies in the positive\npsychological changes after tough life events. Studies show that those\nwho deal with hardships rather than avoid them gain greater self-\nawareness, deeper understanding of others, and a stronger sense of\npurpose. For example, people who survive health problems with resilience\noften adjust their thinking, regaining confidence in their own abilities\nand valuing life more. This growth does not come automatically; it comes\nfrom facing difficulties on purpose, strengthening mental strength just\nas exercise builds muscle.\nResilience also plays an important role in life changes. Young people\nentering the workplace face setbacks such as rejected plans or\ndisagreements that cause self-doubt, but resilient people see these as\nlearning chances. They analyze their mistakes, ask for advice, and\ndevelop skills to make progress. Similarly, people traveling alone\nimprove resilience by dealing with unfamiliar environments on their own,\ntrusting their decisions and adapting to difficulties. Some people argue\nthat focusing on resilience puts pressure on people to ignore pain, but\nresilience means recognizing suffering without being controlled by it.\nIt is a skill that can be developed, not an inborn quality. Simple\nmethods such as changing negative thoughts, building support groups, and\npracticing thanksgiving can strengthen it over time.\nIn a society that values quick solutions, we must realize that true\ngrowth is built on resilience. Difficulties are an essential part of\ngrowth, not a detour. Developing resilience helps us face challenges\nbravely, adapt smoothly, and become stronger. It remains the most\nreliable companion on the path to meaningful personal growth.\n\n【题目】\nWhat is the common misunderstanding about personal growth according to the passage?","options":[{"key":"A","text":"It requires great efforts to achieve."},{"key":"B","text":"It is a smooth process full of achievements."},{"key":"C","text":"It has a close connection with difficulties."},{"key":"D","text":"It can only be gained through work experience."}],"answer":"B","explanation":"句意（题目）：据文章，关于个人成长常见的误解是什么？\n【原文依据】第一段：\"Personal growth is often mistakenly regarded as a smooth upward path of achievements\"（个人成长常被误认为是一条充满成就的、平坦的上升之路）。\"mistakenly（错误地）\"明确点出这是误解。\n【逐项分析】A\"需要付出巨大努力\"、C\"与困难密切相关\"是作者认同的观点，并非\"误解\"；D\"只能通过工作经验获得\"原文未提。故选B（成长是顺利、充满成就的过程）。","chapter":"阅读"},{"id":"english-read-12","origNo":12,"type":"single","stem":"【阅读材料】\nPersonal growth is often mistakenly regarded as a smooth upward path of\nachievements. Yet psychological research and real-life experiences\nconfirm a different truth: resilience — the ability to adapt and develop\namid difficulties  — is the unseen force driving deep and lasting\ngrowth. In an era of rapid changes and unexpected challenges, developing\nresilience is not just a survival skill but a key part of self-\ndevelopment, turning setbacks into stepping stones.\nThe link between difficulties and growth lies in the positive\npsychological changes after tough life events. Studies show that those\nwho deal with hardships rather than avoid them gain greater self-\nawareness, deeper understanding of others, and a stronger sense of\npurpose. For example, people who survive health problems with resilience\noften adjust their thinking, regaining confidence in their own abilities\nand valuing life more. This growth does not come automatically; it comes\nfrom facing difficulties on purpose, strengthening mental strength just\nas exercise builds muscle.\nResilience also plays an important role in life changes. Young people\nentering the workplace face setbacks such as rejected plans or\ndisagreements that cause self-doubt, but resilient people see these as\nlearning chances. They analyze their mistakes, ask for advice, and\ndevelop skills to make progress. Similarly, people traveling alone\nimprove resilience by dealing with unfamiliar environments on their own,\ntrusting their decisions and adapting to difficulties. Some people argue\nthat focusing on resilience puts pressure on people to ignore pain, but\nresilience means recognizing suffering without being controlled by it.\nIt is a skill that can be developed, not an inborn quality. Simple\nmethods such as changing negative thoughts, building support groups, and\npracticing thanksgiving can strengthen it over time.\nIn a society that values quick solutions, we must realize that true\ngrowth is built on resilience. Difficulties are an essential part of\ngrowth, not a detour. Developing resilience helps us face challenges\nbravely, adapt smoothly, and become stronger. It remains the most\nreliable companion on the path to meaningful personal growth.\n\n【题目】\nWhich of the following is NOT a benefit of dealing with hardships actively?","options":[{"key":"A","text":"Gaining a better understanding of oneself."},{"key":"B","text":"Developing a stronger sense of purpose."},{"key":"C","text":"Avoiding all the pain in life."},{"key":"D","text":"Learning to value life more."}],"answer":"C","explanation":"句意（题目）：以下哪项不是积极应对困难带来的益处？\n【原文依据】第二段：积极应对困难能带来\"greater self-awareness（更强自我认知）、deeper understanding of others（对他人更深理解）、stronger sense of purpose（更强目标感）、valuing life more（更珍惜生命）\"。第三段又强调：\"resilience means recognizing suffering without being controlled by it\"（韧性是承认痛苦而不被其控制），并非消除痛苦。\n【逐项分析】A、B、D 都是文中列举的真实益处；C\"避免生活中所有痛苦\"与\"承认痛苦而不被控制\"矛盾，因此不是益处。故选C。","chapter":"阅读"},{"id":"english-read-13","origNo":13,"type":"single","stem":"【阅读材料】\nPersonal growth is often mistakenly regarded as a smooth upward path of\nachievements. Yet psychological research and real-life experiences\nconfirm a different truth: resilience — the ability to adapt and develop\namid difficulties  — is the unseen force driving deep and lasting\ngrowth. In an era of rapid changes and unexpected challenges, developing\nresilience is not just a survival skill but a key part of self-\ndevelopment, turning setbacks into stepping stones.\nThe link between difficulties and growth lies in the positive\npsychological changes after tough life events. Studies show that those\nwho deal with hardships rather than avoid them gain greater self-\nawareness, deeper understanding of others, and a stronger sense of\npurpose. For example, people who survive health problems with resilience\noften adjust their thinking, regaining confidence in their own abilities\nand valuing life more. This growth does not come automatically; it comes\nfrom facing difficulties on purpose, strengthening mental strength just\nas exercise builds muscle.\nResilience also plays an important role in life changes. Young people\nentering the workplace face setbacks such as rejected plans or\ndisagreements that cause self-doubt, but resilient people see these as\nlearning chances. They analyze their mistakes, ask for advice, and\ndevelop skills to make progress. Similarly, people traveling alone\nimprove resilience by dealing with unfamiliar environments on their own,\ntrusting their decisions and adapting to difficulties. Some people argue\nthat focusing on resilience puts pressure on people to ignore pain, but\nresilience means recognizing suffering without being controlled by it.\nIt is a skill that can be developed, not an inborn quality. Simple\nmethods such as changing negative thoughts, building support groups, and\npracticing thanksgiving can strengthen it over time.\nIn a society that values quick solutions, we must realize that true\ngrowth is built on resilience. Difficulties are an essential part of\ngrowth, not a detour. Developing resilience helps us face challenges\nbravely, adapt smoothly, and become stronger. It remains the most\nreliable companion on the path to meaningful personal growth.\n\n【题目】\nWhat can we infer from the passage about resilience?","options":[{"key":"A","text":"It can be improved through certain methods."},{"key":"B","text":"It is a skill that only a few people can have."},{"key":"C","text":"It has nothing to do with life changes."},{"key":"D","text":"It makes people ignore their sufferings."}],"answer":"A","explanation":"句意（题目）：关于韧性，从文中可推断出什么？\n【原文依据】第三段：\"It is a skill that can be developed, not an inborn quality. Simple methods such as changing negative thoughts... can strengthen it over time\"（它是一种可以培养的技能，而非天生品质；改变消极想法等方法能随时间增强它）。\n【逐项分析】B 错：原文说\"可以培养\"，并非\"只有少数人拥有\"；C 错：第三段明确说韧性\"在人生转变中也起重要作用\"；D 错：韧性是\"承认痛苦而不被控制\"，不是\"无视痛苦\"。故选A。","chapter":"阅读"},{"id":"english-read-14","origNo":14,"type":"single","stem":"【阅读材料】\nPersonal growth is often mistakenly regarded as a smooth upward path of\nachievements. Yet psychological research and real-life experiences\nconfirm a different truth: resilience — the ability to adapt and develop\namid difficulties  — is the unseen force driving deep and lasting\ngrowth. In an era of rapid changes and unexpected challenges, developing\nresilience is not just a survival skill but a key part of self-\ndevelopment, turning setbacks into stepping stones.\nThe link between difficulties and growth lies in the positive\npsychological changes after tough life events. Studies show that those\nwho deal with hardships rather than avoid them gain greater self-\nawareness, deeper understanding of others, and a stronger sense of\npurpose. For example, people who survive health problems with resilience\noften adjust their thinking, regaining confidence in their own abilities\nand valuing life more. This growth does not come automatically; it comes\nfrom facing difficulties on purpose, strengthening mental strength just\nas exercise builds muscle.\nResilience also plays an important role in life changes. Young people\nentering the workplace face setbacks such as rejected plans or\ndisagreements that cause self-doubt, but resilient people see these as\nlearning chances. They analyze their mistakes, ask for advice, and\ndevelop skills to make progress. Similarly, people traveling alone\nimprove resilience by dealing with unfamiliar environments on their own,\ntrusting their decisions and adapting to difficulties. Some people argue\nthat focusing on resilience puts pressure on people to ignore pain, but\nresilience means recognizing suffering without being controlled by it.\nIt is a skill that can be developed, not an inborn quality. Simple\nmethods such as changing negative thoughts, building support groups, and\npracticing thanksgiving can strengthen it over time.\nIn a society that values quick solutions, we must realize that true\ngrowth is built on resilience. Difficulties are an essential part of\ngrowth, not a detour. Developing resilience helps us face challenges\nbravely, adapt smoothly, and become stronger. It remains the most\nreliable companion on the path to meaningful personal growth.\n\n【题目】\nWhat does the author think of difficulties in personal growth?","options":[{"key":"A","text":"They are unnecessary obstacles to avoid."},{"key":"B","text":"They are key parts of true personal growth."},{"key":"C","text":"They make people lose confidence easily."},{"key":"D","text":"They can only be solved with quick solutions."}],"answer":"B","explanation":"句意（题目）：作者认为困难在个人成长中处于什么地位？\n【原文依据】末段：\"Difficulties are an essential part of growth, not a detour\"（困难是成长不可或缺的一部分，而非弯路）。\"essential（不可或缺的）\"是作者的态度。\n【逐项分析】A\"应避免的不必要障碍\"与\"不可或缺\"相反；C\"让人轻易失去信心\"与韧性使人更强的主旨矛盾；D\"只能用速效办法解决\"与末段\"这个社会崇尚速效，但真正成长建立在韧性上\"相悖。故选B。","chapter":"阅读"},{"id":"english-read-15","origNo":15,"type":"single","stem":"【阅读材料】\nPersonal growth is often mistakenly regarded as a smooth upward path of\nachievements. Yet psychological research and real-life experiences\nconfirm a different truth: resilience — the ability to adapt and develop\namid difficulties  — is the unseen force driving deep and lasting\ngrowth. In an era of rapid changes and unexpected challenges, developing\nresilience is not just a survival skill but a key part of self-\ndevelopment, turning setbacks into stepping stones.\nThe link between difficulties and growth lies in the positive\npsychological changes after tough life events. Studies show that those\nwho deal with hardships rather than avoid them gain greater self-\nawareness, deeper understanding of others, and a stronger sense of\npurpose. For example, people who survive health problems with resilience\noften adjust their thinking, regaining confidence in their own abilities\nand valuing life more. This growth does not come automatically; it comes\nfrom facing difficulties on purpose, strengthening mental strength just\nas exercise builds muscle.\nResilience also plays an important role in life changes. Young people\nentering the workplace face setbacks such as rejected plans or\ndisagreements that cause self-doubt, but resilient people see these as\nlearning chances. They analyze their mistakes, ask for advice, and\ndevelop skills to make progress. Similarly, people traveling alone\nimprove resilience by dealing with unfamiliar environments on their own,\ntrusting their decisions and adapting to difficulties. Some people argue\nthat focusing on resilience puts pressure on people to ignore pain, but\nresilience means recognizing suffering without being controlled by it.\nIt is a skill that can be developed, not an inborn quality. Simple\nmethods such as changing negative thoughts, building support groups, and\npracticing thanksgiving can strengthen it over time.\nIn a society that values quick solutions, we must realize that true\ngrowth is built on resilience. Difficulties are an essential part of\ngrowth, not a detour. Developing resilience helps us face challenges\nbravely, adapt smoothly, and become stronger. It remains the most\nreliable companion on the path to meaningful personal growth.\n\n【题目】\nWhat is the main idea of the passage?","options":[{"key":"A","text":"The ways to deal with life’s difficulties."},{"key":"B","text":"The importance of quick solutions in modern society."},{"key":"C","text":"Resilience is the key driver of personal growth."},{"key":"D","text":"Different opinions on the role of resilience."}],"answer":"C","explanation":"句意（题目）：本文的主旨是什么？\n【原文依据】全文反复论证：第一段\"resilience... is the unseen force driving deep and lasting growth\"（韧性是推动深度、持久成长的隐形力量），末段\"true growth is built on resilience\"（真正的成长建立在韧性之上）。\n【逐项分析】A\"应对困难的方法\"只是第三段的细节，非主旨；B\"速效办法的重要性\"正是作者要反驳的；D\"对韧性作用的不同观点\"文中未展开对立观点的讨论。故选C（韧性是个人成长的关键驱动力）。","chapter":"阅读"},{"id":"english-read-16","origNo":16,"type":"single","stem":"【阅读材料】\nWaking up just one hour earlier could reduce a person’s risk of major\ndepression by 23%, suggests a sweeping new genetic study. Previous\nobservational studies have shown that night owls are twice as likely to\nsuffer from depression as early risers, regardless of how long they\nsleep. In 2018, senior author Celine Vetter, assistant professor of\nintegrative physiology at CU Boulder, published a long-term study of\n32,000 nurses showing that “early risers” were up to 27% less likely to\ndevelop depression over the course of four years.\nTo get a clearer sense of whether shifting sleep time earlier is truly\nprotective, and how much shift is required, lead author Lyas Daglas, M.\nD．, turned to data from the DNA testing company and ten used a method\ncalled “*Mendelian randomization*” to decipher (破译) cause and effect.\nMore than 340 common genetic variants, including variants in the\nso-called “clock gene” PER2, are known to influence a person’s internal\nclock, and genes collectively explain 12-42% of our sleep time\npreference. The researchers assessed deidentified genetic data on these\nvariants from up to 850,000 individuals, including data from 85,000 who\nhad worn wearable sleep trackers for 7 days and 250,000 who had filled\nout sleep-preference questionnaires. In the largest of these samples,\nabout a third of surveyed people self-identified as early risers, 9%\nwere night owls and the rest were in the middle.\nWith this information in hand, the researchers turned to a different\nsample which included genetic information along with anonymized (匿名的)\nmedical and prescription records and surveys about diagnosis of major\ndepressive disorder. Using new statistical techniques, they asked: do\nthose with genetic variants which *predispose them to be early risers*\nalso have a lower risk of depression? The answer is a firm yes.\nEach-one-hour earlier sleep midpoint (halfway between bedtime and wake\ntime) corresponded with a 23% lower risk of major depressive disorder.\nThis suggests that if someone who normally goes to bed at 1 a.m. goes to\nbed at midnight instead and sleeps the same duration, they could cut\ntheir risk by 23%; if they go to bed at 11 p.m. they could cut it by\nabout 40%.\n\n【题目】\nWhat does the first paragraph mainly talk about?","options":[{"key":"A","text":"The significant role of gene action in depression."},{"key":"B","text":"A new observational study about causes of depression."},{"key":"C","text":"The close relationship between depression and sleep time."},{"key":"D","text":"Whether early risers are less likely to suffer from depression."}],"answer":"C","explanation":"句意（题目）：第一段主要讲什么？\n【原文依据】第一段核心句：\"night owls are twice as likely to suffer from depression as early risers\"（夜猫子患抑郁的概率是早起者的两倍）以及\"early risers were up to 27% less likely to develop depression\"（早起者患抑郁风险最多低27%）。\n【逐项分析】A\"基因在抑郁中的作用\"是后文内容，第一段未展开；B\"关于抑郁成因的观察研究\"不准确，第一段讲的是与\"睡眠时间\"的关联而非泛泛成因；D\"早起者是否更不易抑郁\"只是其中一个侧面，未涵盖\"夜猫子\"这条线索。故选C（抑郁与睡眠时间的密切关系）。","chapter":"阅读"},{"id":"english-read-17","origNo":17,"type":"single","stem":"【阅读材料】\nWaking up just one hour earlier could reduce a person’s risk of major\ndepression by 23%, suggests a sweeping new genetic study. Previous\nobservational studies have shown that night owls are twice as likely to\nsuffer from depression as early risers, regardless of how long they\nsleep. In 2018, senior author Celine Vetter, assistant professor of\nintegrative physiology at CU Boulder, published a long-term study of\n32,000 nurses showing that “early risers” were up to 27% less likely to\ndevelop depression over the course of four years.\nTo get a clearer sense of whether shifting sleep time earlier is truly\nprotective, and how much shift is required, lead author Lyas Daglas, M.\nD．, turned to data from the DNA testing company and ten used a method\ncalled “*Mendelian randomization*” to decipher (破译) cause and effect.\nMore than 340 common genetic variants, including variants in the\nso-called “clock gene” PER2, are known to influence a person’s internal\nclock, and genes collectively explain 12-42% of our sleep time\npreference. The researchers assessed deidentified genetic data on these\nvariants from up to 850,000 individuals, including data from 85,000 who\nhad worn wearable sleep trackers for 7 days and 250,000 who had filled\nout sleep-preference questionnaires. In the largest of these samples,\nabout a third of surveyed people self-identified as early risers, 9%\nwere night owls and the rest were in the middle.\nWith this information in hand, the researchers turned to a different\nsample which included genetic information along with anonymized (匿名的)\nmedical and prescription records and surveys about diagnosis of major\ndepressive disorder. Using new statistical techniques, they asked: do\nthose with genetic variants which *predispose them to be early risers*\nalso have a lower risk of depression? The answer is a firm yes.\nEach-one-hour earlier sleep midpoint (halfway between bedtime and wake\ntime) corresponded with a 23% lower risk of major depressive disorder.\nThis suggests that if someone who normally goes to bed at 1 a.m. goes to\nbed at midnight instead and sleeps the same duration, they could cut\ntheir risk by 23%; if they go to bed at 11 p.m. they could cut it by\nabout 40%.\n\n【题目】\nHow did Lyas Daghlas decipher cause and effect?","options":[{"key":"A","text":"By exploring the influence of genes on depression."},{"key":"B","text":"By analyzing samples of surveyed people’s self-identification."},{"key":"C","text":"By tracking individuals diagnosed with depressive disorder."},{"key":"D","text":"By proving the decisive role sleep time plays in genetic variants."}],"answer":"A","explanation":"句意（题目）：莱亚斯·达格拉斯是如何厘清因果关系的？\n【原文依据】第二段：他借助DNA数据，\"used a method called Mendelian randomization to decipher cause and effect\"（用\"孟德尔随机化\"方法破译因果关系）；并指出\"More than 340 common genetic variants... influence a person's internal clock\"（340多种基因变异影响人体生物钟）。\n【逐项分析】B 错：他用的是基因数据，并非\"自我认同样本\"的分析；C 错：他追踪的是基因变异与抑郁风险的关系，而非\"追踪确诊患者\"；D 错：原文未说睡眠时间对基因变异起\"决定性作用\"，因果方向恰相反。故选A（通过探究基因对抑郁的影响）。","chapter":"阅读"},{"id":"english-read-18","origNo":18,"type":"single","stem":"【阅读材料】\nWaking up just one hour earlier could reduce a person’s risk of major\ndepression by 23%, suggests a sweeping new genetic study. Previous\nobservational studies have shown that night owls are twice as likely to\nsuffer from depression as early risers, regardless of how long they\nsleep. In 2018, senior author Celine Vetter, assistant professor of\nintegrative physiology at CU Boulder, published a long-term study of\n32,000 nurses showing that “early risers” were up to 27% less likely to\ndevelop depression over the course of four years.\nTo get a clearer sense of whether shifting sleep time earlier is truly\nprotective, and how much shift is required, lead author Lyas Daglas, M.\nD．, turned to data from the DNA testing company and ten used a method\ncalled “*Mendelian randomization*” to decipher (破译) cause and effect.\nMore than 340 common genetic variants, including variants in the\nso-called “clock gene” PER2, are known to influence a person’s internal\nclock, and genes collectively explain 12-42% of our sleep time\npreference. The researchers assessed deidentified genetic data on these\nvariants from up to 850,000 individuals, including data from 85,000 who\nhad worn wearable sleep trackers for 7 days and 250,000 who had filled\nout sleep-preference questionnaires. In the largest of these samples,\nabout a third of surveyed people self-identified as early risers, 9%\nwere night owls and the rest were in the middle.\nWith this information in hand, the researchers turned to a different\nsample which included genetic information along with anonymized (匿名的)\nmedical and prescription records and surveys about diagnosis of major\ndepressive disorder. Using new statistical techniques, they asked: do\nthose with genetic variants which *predispose them to be early risers*\nalso have a lower risk of depression? The answer is a firm yes.\nEach-one-hour earlier sleep midpoint (halfway between bedtime and wake\ntime) corresponded with a 23% lower risk of major depressive disorder.\nThis suggests that if someone who normally goes to bed at 1 a.m. goes to\nbed at midnight instead and sleeps the same duration, they could cut\ntheir risk by 23%; if they go to bed at 11 p.m. they could cut it by\nabout 40%.\n\n【题目】\nWhat is Lyas Daghals’s research mainly based on?","options":[{"key":"A","text":"Medical treatment records of early risers."},{"key":"B","text":"The genetic research and data about DNA"},{"key":"C","text":"A comprehensive analysis of different samples."},{"key":"D","text":"250,000 people’s self-identification and questionnaires."}],"answer":"C","explanation":"句意（题目）：莱亚斯·达格拉斯的研究主要基于什么？\n【原文依据】第二、三段：研究综合了多个不同样本——多达85万人的基因数据（850,000 individuals）、8.5万人佩戴睡眠追踪器的数据（85,000 with wearable sleep trackers）、25万份问卷（250,000 questionnaires），第三段又\"turned to a different sample\"（转向另一个样本，含基因信息与医疗处方记录）。即把多个不同样本综合起来分析。\n【逐项分析】A 错：医疗记录只是其中一个样本的一部分，且并非只针对早起者；B 错：研究不止\"基因和DNA\"，还包含睡眠追踪、问卷、医疗记录等多源数据，B 太片面；D 错：25万份问卷只是众多样本之一。故选C（对不同样本的综合分析）。","chapter":"阅读"},{"id":"english-read-19","origNo":19,"type":"single","stem":"【阅读材料】\nWaking up just one hour earlier could reduce a person’s risk of major\ndepression by 23%, suggests a sweeping new genetic study. Previous\nobservational studies have shown that night owls are twice as likely to\nsuffer from depression as early risers, regardless of how long they\nsleep. In 2018, senior author Celine Vetter, assistant professor of\nintegrative physiology at CU Boulder, published a long-term study of\n32,000 nurses showing that “early risers” were up to 27% less likely to\ndevelop depression over the course of four years.\nTo get a clearer sense of whether shifting sleep time earlier is truly\nprotective, and how much shift is required, lead author Lyas Daglas, M.\nD．, turned to data from the DNA testing company and ten used a method\ncalled “*Mendelian randomization*” to decipher (破译) cause and effect.\nMore than 340 common genetic variants, including variants in the\nso-called “clock gene” PER2, are known to influence a person’s internal\nclock, and genes collectively explain 12-42% of our sleep time\npreference. The researchers assessed deidentified genetic data on these\nvariants from up to 850,000 individuals, including data from 85,000 who\nhad worn wearable sleep trackers for 7 days and 250,000 who had filled\nout sleep-preference questionnaires. In the largest of these samples,\nabout a third of surveyed people self-identified as early risers, 9%\nwere night owls and the rest were in the middle.\nWith this information in hand, the researchers turned to a different\nsample which included genetic information along with anonymized (匿名的)\nmedical and prescription records and surveys about diagnosis of major\ndepressive disorder. Using new statistical techniques, they asked: do\nthose with genetic variants which *predispose them to be early risers*\nalso have a lower risk of depression? The answer is a firm yes.\nEach-one-hour earlier sleep midpoint (halfway between bedtime and wake\ntime) corresponded with a 23% lower risk of major depressive disorder.\nThis suggests that if someone who normally goes to bed at 1 a.m. goes to\nbed at midnight instead and sleeps the same duration, they could cut\ntheir risk by 23%; if they go to bed at 11 p.m. they could cut it by\nabout 40%.\n\n【题目】\nHow do you understand the underlined part in the last paragraph?","options":[{"key":"A","text":"Make them more likely to rise early."},{"key":"B","text":"Change early risers’ habits."},{"key":"C","text":"Force them to change their chronotype"},{"key":"D","text":"Lead them to shift sleep time"}],"answer":"A","explanation":"句意（题目）：如何理解文中划线部分\"predispose them to be early risers\"？\n【原文依据】第三段：\"do those with genetic variants which predispose them to be early risers also have a lower risk of depression?\"（带有\"使他们倾向于早起\"的基因变异的人，患抑郁风险是否更低？）。predispose 意为\"使……有倾向\"。\n【逐项分析】B\"改变早起者的习惯\"、C\"强迫他们改变生物钟类型\"、D\"引导他们调整睡眠时间\"都偏离了\"使……倾向于早起（成为早起者）\"的本义。故选A（让他们更可能早起）。","chapter":"阅读"},{"id":"english-read-20","origNo":20,"type":"single","stem":"【阅读材料】\nWaking up just one hour earlier could reduce a person’s risk of major\ndepression by 23%, suggests a sweeping new genetic study. Previous\nobservational studies have shown that night owls are twice as likely to\nsuffer from depression as early risers, regardless of how long they\nsleep. In 2018, senior author Celine Vetter, assistant professor of\nintegrative physiology at CU Boulder, published a long-term study of\n32,000 nurses showing that “early risers” were up to 27% less likely to\ndevelop depression over the course of four years.\nTo get a clearer sense of whether shifting sleep time earlier is truly\nprotective, and how much shift is required, lead author Lyas Daglas, M.\nD．, turned to data from the DNA testing company and ten used a method\ncalled “*Mendelian randomization*” to decipher (破译) cause and effect.\nMore than 340 common genetic variants, including variants in the\nso-called “clock gene” PER2, are known to influence a person’s internal\nclock, and genes collectively explain 12-42% of our sleep time\npreference. The researchers assessed deidentified genetic data on these\nvariants from up to 850,000 individuals, including data from 85,000 who\nhad worn wearable sleep trackers for 7 days and 250,000 who had filled\nout sleep-preference questionnaires. In the largest of these samples,\nabout a third of surveyed people self-identified as early risers, 9%\nwere night owls and the rest were in the middle.\nWith this information in hand, the researchers turned to a different\nsample which included genetic information along with anonymized (匿名的)\nmedical and prescription records and surveys about diagnosis of major\ndepressive disorder. Using new statistical techniques, they asked: do\nthose with genetic variants which *predispose them to be early risers*\nalso have a lower risk of depression? The answer is a firm yes.\nEach-one-hour earlier sleep midpoint (halfway between bedtime and wake\ntime) corresponded with a 23% lower risk of major depressive disorder.\nThis suggests that if someone who normally goes to bed at 1 a.m. goes to\nbed at midnight instead and sleeps the same duration, they could cut\ntheir risk by 23%; if they go to bed at 11 p.m. they could cut it by\nabout 40%.\n\n【题目】\nWhich can be the suitable title for this text?","options":[{"key":"A","text":"Risk of Depression Decreases When Sleeping Time Increases"},{"key":"B","text":"Genes Have More Impact on Depression than Sleep Time Does"},{"key":"C","text":"A New Research Suggests Early Risers Carry Clock Gene called PER2"},{"key":"D","text":"Moving Sleep Time An Hour Earlier Could Cut Depression Risk by 23%"}],"answer":"D","explanation":"句意（题目）：哪个最适合作为本文标题？\n【原文依据】文章核心结论（首段与末段）：\"Waking up just one hour earlier could reduce a person's risk of major depression by 23%\"（早醒一小时可使患重度抑郁症风险降低23%）；末段举例：把入睡时间从凌晨1点提前到午夜可降23%，提前到晚11点可降约40%。\n【逐项分析】A 错：是\"提前睡眠时间\"而非\"增加睡眠时长\"，原文强调时长不变（sleeps the same duration）；B 错：文章重点在睡眠时间，而非断言\"基因影响更大\"；C 错：PER2只是众多\"时钟基因\"之一，且非文章主旨。故选D。","chapter":"阅读"}]};
